-- PREREQUISITE: supabase/migrations/20261023170000_add_hk_mo_tw_2026_star_and_key_cities.sql.
-- One transaction; every check raises and rolls the whole file back.
-- Run: supabase db query --linked -f <absolute path to this file>

begin;

do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'HK';
  if n <> 22 then raise exception 'HK: expected 22 restaurants (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from (values ('rest_0137', 'The Chairman'), ('rest_0301', 'Wing'), ('rest_0441', '8 1/2 Otto e Mezzo - Bombana'), ('rest_0442', 'Amber'), ('rest_0443', 'Caprice'), ('rest_0444', 'Forum'), ('rest_0445', 'Sushi Shikon'), ('rest_0446', 'Ta Vie'), ('rest_0447', 'T''ang Court'), ('rest_0448', 'Arbor'), ('rest_0449', 'Bo Innovation'), ('rest_0450', 'Cristal Room by Anne-Sophie Pic'), ('rest_0451', 'Lai Ching Heen'), ('rest_0452', 'L''Atelier de Joël Robuchon'), ('rest_0453', 'L''Envol'), ('rest_0454', 'Lung King Heen'), ('rest_0455', 'Noi by Paulo Airaudo'), ('rest_0456', 'Octavium'), ('rest_0457', 'Rùn'), ('rest_0458', 'Tate'), ('rest_0459', 'Tin Lung Heen'), ('rest_0460', 'Ying Jee Club')) e(code, name)
   where not exists (select 1 from public.restaurants r where r.restaurant_code = e.code and r.name = e.name and r.country_code = 'HK');
  if n <> 0 then raise exception 'HK: % exported restaurant codes no longer carry their exported name', n; end if;
  select count(*) into n from public.hotels where country_code = 'HK';
  if n <> 5 then raise exception 'HK: expected 5 hotels (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from (values ('hotel_717', 'Four Seasons Hong Kong'), ('hotel_718', 'Mandarin Oriental Hong Kong'), ('hotel_719', 'Rosewood Hong Kong'), ('hotel_720', 'The Peninsula Hong Kong'), ('hotel_721', 'Upper House Hong Kong')) e(code, name)
   where not exists (select 1 from public.hotels h where h.hotel_code = e.code and h.name = e.name and h.country_code = 'HK');
  if n <> 0 then raise exception 'HK: % exported hotel codes no longer carry their exported name', n; end if;
  if exists (select 1 from public.restaurants where restaurant_code ~ '^rest_[0-9]+$'
              and substring(restaurant_code from 6)::int between 2815 and 2870) then
    raise exception 'restaurant codes rest_2815..rest_2870 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.hotels where hotel_code ~ '^hotel_[0-9]+$'
              and substring(hotel_code from 7)::int between 1008 and 1012) then
    raise exception 'hotel codes hotel_1008..hotel_1012 are no longer free -- re-check';
  end if;
  if (select count(distinct guide_year) from public.award_history where award_type = 'michelin_keys' and is_current) > 1
     or exists (select 1 from public.award_history where award_type = 'michelin_keys' and is_current and guide_year <> 2026) then
    raise exception 'current michelin_keys rows are not all guide_year 2026 -- decide the year explicitly';
  end if;
end $$;

