    ('hotel_1012', 'The St. Regis Hong Kong', 1::smallint, 'Hong Kong', '1 Harbour Drive, Hong Kong', 114.17485, 22.28028, 'https://guide.michelin.com/en/hotels-stays/hong-kong-island/the-st-regis-hong-kong-11783', NULL, NULL);
do $$
declare bad text;
begin
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_hotels_hk x
   where (select count(*) from public.cities c where c.country_code = 'HK' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'hotel city does not resolve to exactly one HK row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_hotels_hk x join public.hotels h on h.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'hotel already present (michelin_url): %', bad; end if;
end $$;
insert into public.hotels (hotel_code, name, michelin_keys, city_id, country_code, address, location, michelin_url, website_url, phone)
select x.code, x.name, x.keys,
       (select c.id from public.cities c where c.country_code = 'HK' and c.name = x.city), 'HK',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone
  from _new_hotels_hk x;

-- 1b. Key changes on existing hotels (NULL-safe: a World's 50 Best hotel may hold no Key yet)
create temp table _kchg_hk (code text primary key, keys smallint, was smallint) on commit drop;
insert into _kchg_hk values
    ('hotel_717', 2, 1);
update public.award_history a set is_current = false from public.hotels h, _kchg_hk k
 where h.id = a.entity_id and h.hotel_code = k.code and a.entity_type = 'hotel' and a.award_type = 'michelin_keys' and a.is_current;
update public.hotels h set michelin_keys = k.keys, updated_at = now() from _kchg_hk k
 where h.hotel_code = k.code and h.michelin_keys is not distinct from k.was;

-- 1c. current 2026 Key row for every HK Key hotel that lacks one (the August World's 50 Best import left the
--     existing ones without; PE_REPORT finding 1)
insert into public.award_history (entity_type, entity_id, guide_year, award_type, award_value, is_current, announced_on)
select 'hotel', h.id, 2026, 'michelin_keys', h.michelin_keys, true, date '2026-09-18'
  from public.hotels h
 where h.hotel_code = any(array['hotel_719', 'hotel_717', 'hotel_1008', 'hotel_720', 'hotel_721', 'hotel_1009', 'hotel_718', 'hotel_1010', 'hotel_1011', 'hotel_1012'])
   and not exists (select 1 from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
                    and a.award_type = 'michelin_keys' and a.is_current);

