do $$
declare n int;
begin
  select count(*) into n from _links_hk l
   where not exists (select 1 from public.hotels h where h.hotel_code = l.hotel_code)
      or not exists (select 1 from public.restaurants r where r.restaurant_code = l.restaurant_code);
  if n <> 0 then raise exception '% links point at a missing hotel or restaurant', n; end if;
end $$;
insert into public.hotel_restaurants (hotel_id, restaurant_id, link_confidence, evidence, verified_at)
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_hk l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- post-conditions (HK): MICHELIN's live listing and the 2026 Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'HK' and michelin_stars = 3;
  if n <> 7 then raise exception 'expected 7 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'HK' and michelin_stars = 2;
  if n <> 13 then raise exception 'expected 13 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'HK' and michelin_stars = 1;
  if n <> 57 then raise exception 'expected 57 one-star, found %', n; end if;
  -- rows that hold or ever held a star (a World's 50 Best row MICHELIN never starred, e.g. Wing, has no star history)
  select count(*) into n from public.restaurants r where r.country_code = 'HK'
     and (r.michelin_stars is not null or exists (select 1 from public.award_history ah where ah.entity_type = 'restaurant'
          and ah.entity_id = r.id and ah.award_type = 'michelin_stars'))
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception '% restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'HK' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception '% restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'HK' and r.restaurant_code between 'rest_2815' and 'rest_2870' and ah.guide_year = 2026;
  if n <> 56 then raise exception 'expected 56 new restaurants with a current 2026 row, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'HK' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception '% restaurants have both a hotel link and a property_name', n; end if;
  select count(*) into n from public.hotels where country_code = 'HK' and michelin_keys = 3;
  if n <> 1 then raise exception 'expected 1 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'HK' and michelin_keys = 2;
  if n <> 4 then raise exception 'expected 4 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'HK' and michelin_keys = 1;
  if n <> 5 then raise exception 'expected 5 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'HK' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys) <> 1;
  if n <> 0 then raise exception '% Key hotels without exactly one matching current Key row', n; end if;
  select count(*) into n from public.hotel_restaurants hr join public.hotels h on h.id = hr.hotel_id where h.country_code = 'HK';
  if n <> 15 then raise exception 'expected 15 HK hotel links, found %', n; end if;
end $$;

do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'MO';
  if n <> 7 then raise exception 'MO: expected 7 restaurants (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from (values ('rest_0434', 'Robuchon au Dôme'), ('rest_0435', 'Jade Dragon'), ('rest_0436', 'Wing Lei'), ('rest_0437', 'Alain Ducasse at Morpheus'), ('rest_0438', 'The Eight'), ('rest_0439', 'Feng Wei Ju'), ('rest_0440', 'Chef Tam''s Seasons')) e(code, name)
   where not exists (select 1 from public.restaurants r where r.restaurant_code = e.code and r.name = e.name and r.country_code = 'MO');
  if n <> 0 then raise exception 'MO: % exported restaurant codes no longer carry their exported name', n; end if;
  select count(*) into n from public.hotels where country_code = 'MO';
  if n <> 1 then raise exception 'MO: expected 1 hotels (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from (values ('hotel_798', 'Wynn Palace')) e(code, name)
   where not exists (select 1 from public.hotels h where h.hotel_code = e.code and h.name = e.name and h.country_code = 'MO');
  if n <> 0 then raise exception 'MO: % exported hotel codes no longer carry their exported name', n; end if;
  if exists (select 1 from public.restaurants where restaurant_code ~ '^rest_[0-9]+$'
              and substring(restaurant_code from 6)::int between 2871 and 2884) then
    raise exception 'restaurant codes rest_2871..rest_2884 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.hotels where hotel_code ~ '^hotel_[0-9]+$'
              and substring(hotel_code from 7)::int between 1013 and 1021) then
    raise exception 'hotel codes hotel_1013..hotel_1021 are no longer free -- re-check';
  end if;
  if (select count(distinct guide_year) from public.award_history where award_type = 'michelin_keys' and is_current) > 1
     or exists (select 1 from public.award_history where award_type = 'michelin_keys' and is_current and guide_year <> 2026) then
    raise exception 'current michelin_keys rows are not all guide_year 2026 -- decide the year explicitly';
  end if;
end $$;

