do $$
declare n int;
begin
  select count(*) into n from _links_mo l
   where not exists (select 1 from public.hotels h where h.hotel_code = l.hotel_code)
      or not exists (select 1 from public.restaurants r where r.restaurant_code = l.restaurant_code);
  if n <> 0 then raise exception '% links point at a missing hotel or restaurant', n; end if;
end $$;
insert into public.hotel_restaurants (hotel_id, restaurant_id, link_confidence, evidence, verified_at)
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_mo l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- post-conditions (MO): MICHELIN's live listing and the 2026 Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'MO' and michelin_stars = 3;
  if n <> 2 then raise exception 'expected 2 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'MO' and michelin_stars = 2;
  if n <> 6 then raise exception 'expected 6 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'MO' and michelin_stars = 1;
  if n <> 13 then raise exception 'expected 13 one-star, found %', n; end if;
  -- rows that hold or ever held a star (a World's 50 Best row MICHELIN never starred, e.g. Wing, has no star history)
  select count(*) into n from public.restaurants r where r.country_code = 'MO'
     and (r.michelin_stars is not null or exists (select 1 from public.award_history ah where ah.entity_type = 'restaurant'
          and ah.entity_id = r.id and ah.award_type = 'michelin_stars'))
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception '% restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'MO' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception '% restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'MO' and r.restaurant_code between 'rest_2871' and 'rest_2884' and ah.guide_year = 2026;
  if n <> 14 then raise exception 'expected 14 new restaurants with a current 2026 row, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'MO' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception '% restaurants have both a hotel link and a property_name', n; end if;
  select count(*) into n from public.hotels where country_code = 'MO' and michelin_keys = 3;
  if n <> 1 then raise exception 'expected 1 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'MO' and michelin_keys = 2;
  if n <> 4 then raise exception 'expected 4 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'MO' and michelin_keys = 1;
  if n <> 4 then raise exception 'expected 4 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'MO' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys) <> 1;
  if n <> 0 then raise exception '% Key hotels without exactly one matching current Key row', n; end if;
  select count(*) into n from public.hotel_restaurants hr join public.hotels h on h.id = hr.hotel_id where h.country_code = 'MO';
  if n <> 7 then raise exception 'expected 7 MO hotel links, found %', n; end if;
end $$;

do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'TW';
  if n <> 10 then raise exception 'TW: expected 10 restaurants (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from (values ('rest_0461', 'Le Palais'), ('rest_0462', 'Taïrroir'), ('rest_0463', 'JL Studio'), ('rest_0464', 'A'), ('rest_0465', 'Eika'), ('rest_0466', 'L''Atelier de Joël Robuchon'), ('rest_0467', 'logy'), ('rest_0468', 'Molino de Urdániz'), ('rest_0469', 'Mudan'), ('rest_0470', 'Yu Kapo')) e(code, name)
   where not exists (select 1 from public.restaurants r where r.restaurant_code = e.code and r.name = e.name and r.country_code = 'TW');
  if n <> 0 then raise exception 'TW: % exported restaurant codes no longer carry their exported name', n; end if;
  select count(*) into n from public.hotels where country_code = 'TW';
  if n <> 0 then raise exception 'TW: expected 0 hotels (export), found % -- production changed, re-check', n; end if;
  if exists (select 1 from public.restaurants where restaurant_code ~ '^rest_[0-9]+$'
              and substring(restaurant_code from 6)::int between 2885 and 2935) then
    raise exception 'restaurant codes rest_2885..rest_2935 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.hotels where hotel_code ~ '^hotel_[0-9]+$'
              and substring(hotel_code from 7)::int between 1022 and 1029) then
    raise exception 'hotel codes hotel_1022..hotel_1029 are no longer free -- re-check';
  end if;
  if (select count(distinct guide_year) from public.award_history where award_type = 'michelin_keys' and is_current) > 1
     or exists (select 1 from public.award_history where award_type = 'michelin_keys' and is_current and guide_year <> 2026) then
    raise exception 'current michelin_keys rows are not all guide_year 2026 -- decide the year explicitly';
  end if;
end $$;

