do $$
declare bad text;
begin
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_hotels_tw x
   where (select count(*) from public.cities c where c.country_code = 'TW' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'hotel city does not resolve to exactly one TW row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_hotels_tw x join public.hotels h on h.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'hotel already present (michelin_url): %', bad; end if;
end $$;
insert into public.hotels (hotel_code, name, michelin_keys, city_id, country_code, address, location, michelin_url, website_url, phone)
select x.code, x.name, x.keys,
       (select c.id from public.cities c where c.country_code = 'TW' and c.name = x.city), 'TW',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone
  from _new_hotels_tw x;

-- 1c. current 2026 Key row for every TW Key hotel that lacks one (the August World's 50 Best import left the
--     existing ones without; PE_REPORT finding 1)
insert into public.award_history (entity_type, entity_id, guide_year, award_type, award_value, is_current, announced_on)
select 'hotel', h.id, 2026, 'michelin_keys', h.michelin_keys, true, date '2026-09-18'
  from public.hotels h
 where h.hotel_code = any(array['hotel_1022', 'hotel_1023', 'hotel_1024', 'hotel_1025', 'hotel_1026', 'hotel_1027', 'hotel_1028', 'hotel_1029'])
   and not exists (select 1 from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
                    and a.award_type = 'michelin_keys' and a.is_current);

