    ('rest_2934', 'YUENJI', 1::smallint, 'Taichung', '5 Anhe East Road, Xitun District, Taichung 407022', 120.6236048, 24.1743625, 'https://guide.michelin.com/en/taichung-region/taichung/restaurant/yuen-ji', 'https://yuen-ji.com/', '+886 4 2358 6368', NULL, NULL, 2026, date '2026-07-21'),
    ('rest_2935', 'ZEA', 1::smallint, 'Taipei', '5, Alley 20, Lane 300, Section 4, Ren''ai Road, Da’an District, Taipei', 121.5541294, 25.03634, 'https://guide.michelin.com/en/taipei-region/taipei/restaurant/zea', NULL, NULL, NULL, NULL, 2026, date '2026-07-21');
do $$
declare bad text;
begin
  select string_agg(x.code, ', ') into bad from _new_tw x join public.restaurants r on r.restaurant_code = x.code;
  if bad is not null then raise exception 'codes no longer free: %', bad; end if;
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_tw x
   where (select count(*) from public.cities c where c.country_code = 'TW' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'city does not resolve to exactly one TW row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_tw x join public.restaurants r on r.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'already present (michelin_url): %', bad; end if;
end $$;
insert into public.restaurants (restaurant_code, name, michelin_stars, inclusion_reason, city_id, country_code,
                                address, location, michelin_url, website_url, phone, property_name, google_place_id)
select x.code, x.name, x.stars, 'michelin_star',
       (select c.id from public.cities c where c.country_code = 'TW' and c.name = x.city), 'TW',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone, x.property_name, x.place_id
  from _new_tw x;
insert into public.award_history (entity_type, entity_id, guide_year, award_type, award_value, is_current, announced_on)
select 'restaurant', r.id, x.guide_year, 'michelin_stars', x.stars, true, x.announced_on
  from _new_tw x join public.restaurants r on r.restaurant_code = x.code;

-- 5. existing restaurants, fill-only (never overwrites)
create temp table _fill_tw (code text primary key, phone text, website_url text, michelin_url text, property_name text) on commit drop;
