update public.restaurants r set phone = f.phone, updated_at = now() from _fill_tw f where r.restaurant_code = f.code and f.phone is not null and r.phone is null;
update public.restaurants r set website_url = f.website_url, updated_at = now() from _fill_tw f where r.restaurant_code = f.code and f.website_url is not null and r.website_url is null;
update public.restaurants r set michelin_url = f.michelin_url, updated_at = now() from _fill_tw f where r.restaurant_code = f.code and f.michelin_url is not null and r.michelin_url is null;
update public.restaurants r set property_name = f.property_name, updated_at = now() from _fill_tw f where r.restaurant_code = f.code and f.property_name is not null and r.property_name is null
   and not exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);

-- 6. links to hotels in `hotels`
create temp table _links_tw (hotel_code text, restaurant_code text, confidence text, evidence text) on commit drop;
insert into _links_tw values
    ('hotel_1022', 'rest_2908', 'exact', 'MICHELIN restaurant page address ''2F, Capella, 139 Dunhua North Road, Songshan District, Taipei 105021'' places it in Capella Taipei; MICHELIN''s Key hotel page (2 Key(s)) gives ''No. 139 Dunhua North Road, Songshan District'' (same street number); points 81 m apart. 2026-10-29.'),
    ('hotel_1026', 'rest_2932', 'exact', 'MICHELIN restaurant page ''Stay at the hotel'' -> /en/hotels-stays/taipei/mandarin-oriental-taipei-7573 (Mandarin Oriental Taipei); MICHELIN''s Key hotel page (1 Key(s)) gives ''158 Dunhua North Road'' (same street number); points 2 m apart. 2026-10-29.');
do $$
declare n int;
begin
  select count(*) into n from _links_tw l
   where not exists (select 1 from public.hotels h where h.hotel_code = l.hotel_code)
      or not exists (select 1 from public.restaurants r where r.restaurant_code = l.restaurant_code);
  if n <> 0 then raise exception '% links point at a missing hotel or restaurant', n; end if;
end $$;
insert into public.hotel_restaurants (hotel_id, restaurant_id, link_confidence, evidence, verified_at)
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_tw l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- post-conditions (TW): MICHELIN's live listing and the 2026 Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'TW' and michelin_stars = 3;
  if n <> 3 then raise exception 'expected 3 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'TW' and michelin_stars = 2;
  if n <> 9 then raise exception 'expected 9 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'TW' and michelin_stars = 1;
  if n <> 49 then raise exception 'expected 49 one-star, found %', n; end if;
  -- rows that hold or ever held a star (a World's 50 Best row MICHELIN never starred, e.g. Wing, has no star history)
  select count(*) into n from public.restaurants r where r.country_code = 'TW'
     and (r.michelin_stars is not null or exists (select 1 from public.award_history ah where ah.entity_type = 'restaurant'
          and ah.entity_id = r.id and ah.award_type = 'michelin_stars'))
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception '% restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'TW' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception '% restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'TW' and r.restaurant_code between 'rest_2885' and 'rest_2935' and ah.guide_year = 2026;
  if n <> 51 then raise exception 'expected 51 new restaurants with a current 2026 row, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'TW' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception '% restaurants have both a hotel link and a property_name', n; end if;
  select count(*) into n from public.hotels where country_code = 'TW' and michelin_keys = 3;
  if n <> 0 then raise exception 'expected 0 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'TW' and michelin_keys = 2;
  if n <> 1 then raise exception 'expected 1 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'TW' and michelin_keys = 1;
  if n <> 7 then raise exception 'expected 7 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'TW' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys) <> 1;
  if n <> 0 then raise exception '% Key hotels without exactly one matching current Key row', n; end if;
  select count(*) into n from public.hotel_restaurants hr join public.hotels h on h.id = hr.hotel_id where h.country_code = 'TW';
  if n <> 2 then raise exception 'expected 2 TW hotel links, found %', n; end if;
end $$;

commit;
